using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Reflection;
using ImageGuide;
namespace WinISOPilot.Desktop;
public static class DesktopSelfTests
{
    public static void Run()
    {
        int count=0;void Check(string name,Action action){action();count++;Console.WriteLine("PASS "+name);}
        Check("WPF preview changes remain nonexecuting",()=>{var session=new Session();session.Change(()=>session.Preview=session.Preview with{Requested=["tpm"]});if(session.Preview.Executable||session.UndoCount!=1)throw new Exception();session.Undo();if(session.ChangeCount!=0)throw new Exception();});
        Check("WPF rejected preview mutation rolls back atomically",()=>{var session=new Session();try{session.Change(()=>session.Preview=session.Preview with{Requested=["invalid"]});throw new Exception("Invalid preview accepted");}catch(System.IO.InvalidDataException){}if(session.ChangeCount!=0||session.UndoCount!=0)throw new Exception();});
        Check("WPF service choice removal preserves other choices and Undo",()=>{var session=new Session();session.Change(()=>session.Preview=session.Preview with{Requested=["xbox"],Services=new(){{"Spooler","Manual"}}});session.Remove("service:Spooler");if(session.Preview.Services.Count!=0||session.Preview.Requested.Length!=1)throw new Exception();session.Undo();if(session.Preview.Services["Spooler"]!="Manual")throw new Exception();});
        Check("WPF edition change clears explicit confirmation",()=>{var session=new Session{EditionIndex=1,EditionConfirmed=true};session.Change(()=>session.EditionIndex=6);if(session.EditionConfirmed)throw new Exception();session.EditionConfirmed=true;session.Undo();if(session.EditionConfirmed||session.EditionIndex!=1)throw new Exception();});
        Check("WPF preview never grants build capability",()=>{var session=new Session();session.Change(()=>session.Preview=session.Preview with{Requested=PreviewRecipe.Options.Select(x=>x.Id).ToArray()});if(session.Capability(9,false)!="Needs inspection")throw new Exception();});
        Check("WPF local search is bounded and stable",()=>{var entries=Session.Search("preview");if(entries.Count>50||entries.Select(x=>x.Id).Distinct().Count()!=entries.Count||Session.Search("").Count!=0)throw new Exception();});
        Check("WPF search finds friendly service aliases and actual actions",()=>{if(!Session.Search("printing").Any(x=>x.Id=="service:Spooler")||!Session.Search("inspect").Any(x=>x.Id=="Inspect ISO"))throw new Exception();});
        Check("WPF selection history has bounded lifetime",()=>{var session=new Session();for(int i=0;i<150;i++)session.Change(()=>session.PreferEdition=!session.PreferEdition);if(session.UndoCount!=100)throw new Exception();});
        var app=System.Windows.Application.Current??new System.Windows.Application();
        Check("WPF ten workspace views construct without jobs",()=>{var window=new PilotWindow();for(int i=0;i<10;i++){window.Navigate(i);if(window.Busy||window.State.Inspection!=null)throw new Exception();}window.Close();});
        Check("WPF main window fixed canonical size",()=>{var window=new PilotWindow();if(window.Width!=1280||window.Height!=800||window.ResizeMode!=ResizeMode.CanMinimize)throw new Exception();window.Close();});
        Check("WPF phase ring uses only valid observed byte totals",()=>{var ring=new ProgressRing();ring.Observe(new("Copying","Working",50,100));if(ring.Ratio!=.5)throw new Exception();ring.Observe(new("Final verification","Working"));if(ring.Ratio!=null)throw new Exception();ring.Observe(new("Invalid","Working",200,100));if(ring.Ratio!=null)throw new Exception();});
        Check("WPF all ten views measure at canonical and clamped widths",()=>{var window=new PilotWindow();foreach(double width in new[]{1280d,1024d,800d})for(int i=0;i<10;i++){window.Navigate(i);window.MeasureForTests(width,800,i>0);if(!double.IsFinite(window.LayoutRoot.DesiredSize.Width)||window.Stepper.RenderSize.Width>width-36+1)throw new Exception("Unbounded workspace layout");foreach(FrameworkElement button in LogicalTreeHelper.GetChildren(window.Stepper).OfType<FrameworkElement>()){var rect=button.TransformToAncestor(window.LayoutRoot).TransformBounds(new Rect(button.RenderSize));if(rect.Right>window.LayoutRoot.RenderSize.Width+1||rect.Left<0)throw new Exception("Stepper overflow at "+width);}}window.Close();});
        Check("WPF canonical sidebar exposes ten workspaces without scrolling",()=>{var window=new PilotWindow();window.MeasureForTests(1280,800,true);var bounds=window.WorkspaceButtons.Select(x=>x.TransformToAncestor(window.LayoutRoot).TransformBounds(new Rect(x.RenderSize))).ToArray();if(bounds.Length!=10||bounds.Any(x=>x.Bottom>window.LayoutRoot.RenderSize.Height-60||x.Left<0))throw new Exception("Navigation extends below fixed shell: "+string.Join("; ",bounds.Select(x=>x.ToString()))+" root="+window.LayoutRoot.RenderSize);window.Close();});
        Check("WPF source Inspect action remains above viewport fold",()=>{var window=new PilotWindow();window.MeasureForTests(1280,800);var button=window.FindTarget("Inspect ISO")!;var rect=button.TransformToAncestor(window.ContentHost).TransformBounds(new Rect(button.RenderSize));if(rect.Bottom>window.ContentHost.RenderSize.Height||rect.Left<0)throw new Exception("Inspect action below fold: "+rect+" / "+window.ContentHost.RenderSize);window.Close();});
        Check("WPF source cards fit within scroll viewport width",()=>{var window=new PilotWindow();window.MeasureForTests(1280,800);var scroll=(ScrollViewer)((ContentControl)window.ContentHost).Content;var page=(FrameworkElement)scroll.Content;if(page.RenderSize.Width>scroll.ViewportWidth+1)throw new Exception("Source page overflows scrollbar: "+page.RenderSize+" / "+scroll.ViewportWidth);window.Close();});
        Check("WPF busy state disables all preview and job mutations at critical boundary",()=>{var window=new PilotWindow();var flags=BindingFlags.NonPublic|BindingFlags.Instance;typeof(PilotWindow).GetField("busy",flags)!.SetValue(window,true);typeof(PilotWindow).GetField("critical",flags)!.SetValue(window,true);using var control=new JobControl();typeof(PilotWindow).GetField("job",flags)!.SetValue(window,control);window.Navigate(1);if(window.FindTarget("option:tpm")!.IsEnabled)throw new Exception("Busy preview toggle active");var pause=(Button)typeof(PilotWindow).GetField("pause",flags)!.GetValue(window)!;var cancel=(Button)typeof(PilotWindow).GetField("cancel",flags)!.GetValue(window)!;if(pause.IsEnabled||cancel.IsEnabled)throw new Exception("Critical work controls active");typeof(PilotWindow).GetField("busy",flags)!.SetValue(window,false);window.Close();});
        Check("WPF source invalidation clears result and confirmation",()=>{var session=new Session{Source="C:\\fixture.iso",EditionConfirmed=true,EditionIndex=1,Result=new MediaBuildResult(Guid.NewGuid(),"C:\\new.iso","A","B","Created",[],[])};session.Invalidate();if(session.EditionConfirmed||session.EditionIndex!=0||session.Result!=null||session.Inspection!=null)throw new Exception();});
        Check("WPF search navigation cannot grant engine state",()=>{var window=new PilotWindow();var before=window.State.Capture();foreach(var entry in Session.Search("TPM"))window.Navigate(entry.Workspace);if(window.State.Capture()!=before||window.Busy)throw new Exception();window.Close();});
        Check("WPF research families remain searchable read-only references",()=>{if(CapabilityCatalog.Items.Count!=42||!Session.Search("language").Any(x=>x.Id.StartsWith("reference:",StringComparison.Ordinal)))throw new Exception();var before=PreviewRecipe.Serialize(PreviewRecipe.Empty);_ = Session.Search("driver");if(PreviewRecipe.Serialize(PreviewRecipe.Empty)!=before)throw new Exception();});
        Check("WPF live job text and ring share current observations",()=>{var window=new PilotWindow();var flags=BindingFlags.NonPublic|BindingFlags.Instance;typeof(PilotWindow).GetField("busy",flags)!.SetValue(window,true);typeof(PilotWindow).GetField("progress",flags)!.SetValue(window,new JobProgress("Copying fixture","Working",50,100));window.Navigate(9);window.MeasureForTests(1280,800);var ring=(ProgressRing)typeof(PilotWindow).GetField("mainRing",flags)!.GetValue(window)!;var text=(TextBlock)typeof(PilotWindow).GetField("mainJobText",flags)!.GetValue(window)!;if(ring.Ratio!=.5||!text.Text.Contains("50 bytes observed")||!text.Text.Contains("Copying fixture"))throw new Exception("Live fields disagree");var rect=ring.TransformToAncestor(window.ContentHost).TransformBounds(new Rect(ring.RenderSize));if(rect.Top<0||rect.Bottom>window.ContentHost.RenderSize.Height)throw new Exception("Active progress buried below review");typeof(PilotWindow).GetField("busy",flags)!.SetValue(window,false);window.Close();});
        Check("WPF ComboBox effective selection template has matched contrast",()=>{var window=new PilotWindow();foreach(bool dark in new[]{true,false}){typeof(PilotWindow).GetField("dark",BindingFlags.Instance|BindingFlags.NonPublic)!.SetValue(window,dark);typeof(PilotWindow).GetMethod("ApplyPalette",BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(window,null);window.Navigate(5);window.MeasureForTests(1280,800,true);var combo=(ComboBox)window.FindTarget("service:Spooler")!;combo.ApplyTemplate();combo.UpdateLayout();var frame=combo.Template.FindName("SelectionFrame",combo) as Border??throw new Exception("Native chrome was not replaced");var presenter=(ContentPresenter)combo.Template.FindName("SelectedValue",combo);IEnumerable<DependencyObject> Descendants(DependencyObject parent){for(int i=0;i<VisualTreeHelper.GetChildrenCount(parent);i++){var child=VisualTreeHelper.GetChild(parent,i);yield return child;foreach(var nested in Descendants(child))yield return nested;}}var selected=Descendants(presenter).OfType<TextBlock>().Single(x=>x.Text=="Unchanged");var background=(frame.Background as SolidColorBrush)?.Color??throw new Exception("No painted field background");var foreground=(selected.Foreground as SolidColorBrush)?.Color??throw new Exception("No effective selected text");double contrast=ShellPalette.Contrast(System.Drawing.Color.FromArgb(background.R,background.G,background.B),System.Drawing.Color.FromArgb(foreground.R,foreground.G,foreground.B));if(contrast<4.5)throw new Exception("Effective selector contrast "+contrast);}window.Close();});
        Check("WPF choice changes and Undo clear completed guide facts",()=>{var session=new Session{Inspection=new Inspection(1,"C:\\fixture.iso","HASH","now","released","owned",[],[],"Unknown","fixture"),EditionConfirmed=true,GuideStage=4,Result=new MediaBuildResult(Guid.NewGuid(),"C:\\new.iso","A","B","Created",[],[])};session.Change(()=>session.PreferEdition=true);if(session.Result!=null||session.GuideStage!=3)throw new Exception("Stale completed guide after choice change");session.GuideStage=4;session.Result=new MediaBuildResult(Guid.NewGuid(),"C:\\new.iso","A","B","Created",[],[]);session.Undo();if(session.Result!=null||session.GuideStage!=3)throw new Exception("Stale completed guide after Undo");});
        Check("WPF selected search and edition text paints readable bounded content",()=>{var window=new PilotWindow();var flags=BindingFlags.Instance|BindingFlags.NonPublic;IEnumerable<DependencyObject> Descendants(DependencyObject parent){for(int i=0;i<VisualTreeHelper.GetChildrenCount(parent);i++){var child=VisualTreeHelper.GetChild(parent,i);yield return child;foreach(var nested in Descendants(child))yield return nested;}}void Verify(ListBoxItem item,ListBox list){item.ApplyTemplate();item.UpdateLayout();var texts=Descendants(item).OfType<TextBlock>().Where(x=>!string.IsNullOrEmpty(x.Text)).ToArray();var backgrounds=item.Background is LinearGradientBrush gradient?gradient.GradientStops.Select(x=>x.Color):[(item.Background as SolidColorBrush)!.Color];foreach(var text in texts){var color=(text.Foreground as SolidColorBrush)?.Color??throw new Exception("No actual foreground");foreach(var background in backgrounds)if(ShellPalette.Contrast(System.Drawing.Color.FromArgb(background.R,background.G,background.B),System.Drawing.Color.FromArgb(color.R,color.G,color.B))<4.5)throw new Exception("Effective selected text contrast failed");if(text.RenderSize.Width>list.RenderSize.Width+1)throw new Exception("Unbounded selected text");}if(ScrollViewer.GetHorizontalScrollBarVisibility(list)!=ScrollBarVisibility.Disabled)throw new Exception("Horizontal list scroll enabled");}
            foreach(bool dark in new[]{true,false}){typeof(PilotWindow).GetField("dark",flags)!.SetValue(window,dark);typeof(PilotWindow).GetMethod("ApplyPalette",flags)!.Invoke(window,null);window.MeasureForTests(900,800);var list=new ListBox{Height=330};var entry=new SearchEntry("fixture","Printing",string.Join(' ',Enumerable.Repeat("A deliberately long research description with no image state.",30)),5);var item=(ListBoxItem)typeof(PilotWindow).GetMethod("CreateSearchItem",flags)!.Invoke(window,[entry])!;list.Items.Add(item);((ContentControl)window.ContentHost).Content=list;for(int i=0;i<3;i++){window.LayoutRoot.Measure(new Size(864,738));window.LayoutRoot.Arrange(new Rect(0,0,864,738));window.LayoutRoot.UpdateLayout();}item.IsSelected=true;Verify(item,list);item.IsSelected=false;Verify(item,list);
                window.State.CompleteInspection(new Inspection(1,"C:\\fixture.iso","HASH","now","released","owned",[new Edition(1,"Windows 11 Home","x64","10.0.26100.1",26100,"Client","Core")],[],"Unknown","fixture"),"fixture.json");window.Navigate(0);window.MeasureForTests(1280,800);var editions=(ListBox)window.FindTarget("Edition list")!;var selected=(ListBoxItem)editions.Items[0];Verify(selected,editions);selected.IsSelected=false;Verify(selected,editions);}window.Close();});
        Check("WPF edition selection preserves live list for repeated keyboard movement",()=>{var window=new PilotWindow();var editions=Enumerable.Range(1,11).Select(i=>new Edition(i,"Edition "+i,"x64","10.0.26100.1",26100,"Client","Core")).ToList();window.State.CompleteInspection(new Inspection(1,"C:\\fixture.iso","HASH","now","released","owned",editions,[],"Unknown","fixture"),"fixture.json");window.Navigate(0);window.MeasureForTests(1280,800);var list=(ListBox)window.FindTarget("Edition list")!;for(int i=0;i<11;i++){list.SelectedIndex=i;if(!ReferenceEquals(list,window.FindTarget("Edition list"))||window.State.EditionIndex!=i+1||window.State.EditionConfirmed)throw new Exception("Edition list recreated or confirmation stale");}window.Close();});
        Console.WriteLine(count+" WPF desktop tests passed.");
    }
}
